{
  "name": "fast-opencode-compaction",
  "version": "0.1.0",
  "description": "Native opencode V2 plugin that prunes stale tool calls and results from the outgoing request using a typed-decision endpoint.",
  "type": "module",
  "license": "MIT",
  "private": true,
  "repository": { "type": "git", "url": "git+https://github.com/augustoolucas/fast-opencode-compaction.git" },
  "keywords": ["opencode", "opencode-plugin", "compaction", "context", "pruning", "jev", "system-one"],
  "engines": {
    "opencode": ">=2"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "fast-jev-compaction": "^0.4.0"
  },
  "devDependencies": {
    "@opencode/ai": "2.0.14",
    "@opencode/plugin": "2.0.14",
    "@types/node": "^24.13.6",
    "typescript": "^7.0.2",
    "vitest": "^5.0.1"
  },
  "exports": {
    ".": "./src/index.ts",
    "./server": "./src/server.ts"
  }
}
